async function cdqPreparerQuvre4Pwa(){
  if(cdqQuvrePreparation)return cdqQuvrePreparation;
  if(cdqAccessState!=='ready' || !navigator.onLine)return;
  const email=utilisateurCourantEmail;
  cdqQuvrePreparation=(async function(){
    cdqPublierSessionHorsLigne();
    for(const modeleId of ['plancher','cuve4','precision','camion','cuve3']){
      if(email!==utilisateurCourantEmail || cdqAccessState!=='ready' || !navigator.onLine)break;
      try{
        await cdqV2112EnsureTemplateOfflineCached(false,modeleId);
        const rec=await cdqV2112GetCachedTemplate(modeleId);
        if(rec && email===utilisateurCourantEmail && cdqAccessState==='ready'){
          const blobRapport=await cdqPersonnaliserBlobTechnicienPdf(rec.blob);
          cdqPostToPwa({type:'CDQ_OFFLINE_TEMPLATE',email:email,modeleId:modeleId,blob:blobRapport,
            templateId:rec.templateId,modifieLe:rec.modifieLe,revision:rec.revision,sha256:"",name:CDQ_MODELES_INTERMEDIAIRES[modeleId]});
        }
      }catch(e){console.warn('Modèle '+modeleId+' : '+(e.message||e));}
    }
  })().catch(function(e){console.warn('Préparation de Balance Quvre 4 : '+(e.message||e));})
    .finally(function(){cdqQuvrePreparation=null;});
  return cdqQuvrePreparation;
}

